-- Guides créateur par zone de paiement (A/B/C).
-- Ne touche PAS à guide_poster : les comptes déjà créés le gardent.
-- Les nouveaux posters sont routés vers ces cles par posterGuideCle.

with src as (
  select $guide_zone_a$<style>
.guide-zone table{width:100%;border-collapse:collapse;margin:12px 0}
.guide-zone th,.guide-zone td{border:1px solid #e4e4e7;padding:8px 10px;text-align:left;vertical-align:top}
.guide-zone th{background:#f4f4f5}
</style><div class="guide-zone"><p>SOPHIA · TIKTOK SLIDESHOW PROGRAMME</p><p><strong>Creator Guide</strong></p><p>Your onboarding — read this first</p><p>Welcome to the team. This is your onboarding document — everything you need, in one place. It covers what the job is, how you get paid, how to set up and warm up your TikTok account, how to publish a slideshow, and what decides whether you continue after the trial week. Your hiring manager sent you this along with your login; there is nothing else to read.</p><table><thead><tr><th><p><strong>Read this fully before your first post.</strong></p><p>Almost every problem we see — no views, a paused contract, a rejected post — comes from skipping something in here. Fifteen minutes now saves you a lot of trouble.</p></th></tr></thead></table><h2><strong>Your login</strong></h2><p>Your hiring manager fills these in for you. Keep them somewhere safe.</p><table><thead><tr><th><p><strong>Platform</strong></p></th><th><p>https://sophia-marketing-orga.vercel.app</p></th></tr><tr><th><p><strong>Your email</strong></p></th><th><p>First name + first letter of your last name @sophia.com</p></th></tr><tr><th><p><strong>Your password</strong></p></th><th><p>12345678</p></th></tr><tr><th><p><strong>Your hiring manager</strong></p></th><th><p>The person who sent you this document — reach them on Upwork or Slack</p></th></tr></thead></table><table><thead><tr><th><p><strong>Your first day, in four moves:</strong></p><p>1. Log in to the platform and read this guide.  2. Create your TikTok account with the exact handle shown in your space.  3. Press “Start warm-up” and leave it 24 hours.  4. Your slideshows appear the next day — then you post twice a day, every day.</p></th></tr></thead></table><h1><strong>1. Your checklist</strong></h1><p>The whole job on one page. Everything is explained in detail further down.</p><h2><strong>Before your first post</strong></h2><ul><li>Log in to the Sophia platform with the details your manager sent you.</li><li>Read this guide.</li><li>Create your TikTok account with the exact handle shown in your space.</li><li>Use your own email address for it — an existing one or a new one you create.</li><li>Press “Start warm-up” on the platform.</li><li>Use TikTok normally for 24 hours — scroll, like, follow, comment.</li><li>Wait for your slideshows to appear in your calendar the next day.</li><li>Join Slack.</li></ul><h2><strong>Every single day</strong></h2><ul><li>Open the platform and find today's slideshows in your calendar.</li><li>Download the images.</li><li>Build post 1 on TikTok — correct order, caption provided, sound provided.</li><li>Publish it and paste the link back on the platform.</li><li>Do the same for post 2, later in the day.</li><li>Check the comments on your recent posts and reply.</li><li>Check for any review your manager sent you and fix it on the next post.</li></ul><table><thead><tr><th><p><strong>2 posts per day, 7 days a week — including during your trial week.</strong></p><p>There is no 1-post-per-day period. It is two from your very first posting day.</p></th></tr></thead></table><h1><strong>2. What you are doing</strong></h1><p>You are helping to promote Sophia, a general knowledge app. We promote it by posting slideshows on TikTok — images with text on them.</p><p>Here is an example: <a href="https://www.tiktok.com/@studyavec_lea/photo/7660178099220352289">view the post on TikTok</a></p><p>All images, captions and sounds are prepared for you. Your job is to assemble them into a TikTok slideshow, publish it, and paste the link back on the platform — twice a day, every day.</p><table><thead><tr><th><p><strong>The task itself is simple. The value you bring is consistency: posting every single day, at good times, with tidy formatting.</strong></p></th></tr></thead></table><h2><strong>Your terms</strong></h2><table><thead><tr><th><p><strong>Trial week</strong></p></th><th><p>$15 fixed — set up your account, warm it up, then post</p></th></tr><tr><th><p><strong>After the trial</strong></p></th><th><p>$60 per month fixed</p></th></tr><tr><th><p><strong>Posting volume</strong></p></th><th><p>2 posts per day, 7 days a week — from your first posting day</p></th></tr><tr><th><p><strong>Sound</strong></p></th><th><p>You use the sound provided with each slideshow on the system</p></th></tr><tr><th><p><strong>Post links</strong></p></th><th><p>Pasted back on the platform after each post</p></th></tr><tr><th><p><strong>Contract type</strong></p></th><th><p>Fixed price, through Upwork</p></th></tr><tr><th><p><strong>Language</strong></p></th><th><p>You publish only in your own language</p></th></tr><tr><th><p><strong>Location</strong></p></th><th><p>You must be physically present in your country</p></th></tr><tr><th><p><strong>Growing</strong></p></th><th><p>Strong creators can manage more than one account — up to $60/month each</p></th></tr></thead></table><h2><strong>Continuing after the trial week</strong></h2><table><thead><tr><th><p><strong>The trial week decides whether you continue. It is not automatic.</strong></p><p>We continue with creators who post good-quality slideshows, post consistently twice a day at sensible times, and whose account is actually getting views. If the quality is sloppy, the posting is irregular, or the account gets no traction, the contract ends at the end of the trial week.</p></th></tr></thead></table><p>So treat the trial week as the real thing, because it is. The three things we look at:</p><ol><li>Quality — slides well formatted, correct sound, correct every day.</li><li>Consistency — 2 posts a day, every day, at stable times.</li><li>Views — the account is getting traction, not flat or shadow-banned.</li></ol><h1><strong>3. Getting set up</strong></h1><h2><strong>Step 1 — Log in to the platform</strong></h2><p>Go to <a href="https://sophia-marketing-orga.vercel.app/">sophia-marketing-orga.vercel.app</a> and sign in with the details your manager sent you:</p><table><thead><tr><th><p><strong>Email</strong></p></th><th><p>Your first name + the first letter of your last name @sophia.com (e.g. maximilienk@sophia.com)</p></th></tr><tr><th><p><strong>Password</strong></p></th><th><p>12345678</p></th></tr></thead></table><p>Once you are in, you will see your own space: the slideshows assigned to you, your calendar, your TikTok account details, and the place to paste your post links.</p><p>You can also use the platform on your phone — that is usually the easiest way to download the images before building a post.</p><h2><strong>Step 2 — Create your TikTok account</strong></h2><p>Your platform space shows you the exact TikTok identity to use — the handle, the name, and the profile details. Create the account with exactly those details. Do not invent a different handle: your manager needs to be able to find your account.</p><p><strong>For the email address on the TikTok account, use your own — either an email you already have, or a new one you create for this. It is your account to manage.</strong></p><ol><li>Open TikTok and create a new account.</li><li>Use your own email address (existing or newly created).</li><li>Use exactly the handle and details shown in your Sophia space.</li><li>Verify the account (email or phone, as TikTok asks).</li><li>Send the link to your TikTok profile to your manager.</li></ol><h2><strong>Step 3 — Warm up the account</strong></h2><p>On the platform there is a button: “Start warm-up”. Press it when you are ready to begin.</p><p>From that moment you have 24 hours of warm-up. During those 24 hours, use TikTok like a normal person:</p><ul><li>Scroll the For You page for a few minutes at a time, several times across the day</li><li>Like posts you genuinely find interesting</li><li>Follow accounts in your own language, in the general knowledge / educational niche</li><li>Comment on a few posts</li><li>Repost something you like</li></ul><p>Interact with creators in your own language and in the general knowledge niche specifically. That is what tells TikTok what your account is about.</p><p>24 hours after you press the button, your slideshows appear in your calendar — and you start posting the day after.</p><table><thead><tr><th><p><strong>This is the single most important step in this guide. Do not skip it and do not start posting early.</strong></p><p>A brand-new account that starts posting immediately gets shadow-banned — your posts get no views, and it cannot be undone. You would have to create a new account and start again.</p></th></tr></thead></table><h1><strong>4. Publishing a slideshow</strong></h1><h2><strong>The routine</strong></h2><ol><li>Open your space on the platform and find today's slideshows in your calendar.</li><li>Download the images (easiest on your phone).</li><li>Open TikTok, start a new post, and select the images in the correct order.</li><li>Add the caption provided.</li><li>Add the sound provided with the slideshow on the system.</li><li>Check every slide is readable and correctly formatted.</li><li>Publish.</li><li>Copy the link of the published post and paste it back on the platform.</li></ol><table><thead><tr><th><p><strong>Two things people get wrong here:</strong></p><p>1. The sound is not your choice. Each slideshow comes with a sound on the system — use that one.</p><p>2. The post link goes on the platform, not in Slack. That is how we know you posted.</p></th></tr></thead></table><h2><strong>Timing</strong></h2><p>Post twice a day, at busy times, and at roughly the same times each day. Consistency matters more than picking the perfect minute — TikTok rewards accounts that behave predictably.</p><ul><li>Spread your two posts out — for example one in the morning, one in the evening</li><li>Aim for peak hours in your own country's time zone</li><li>Keep to roughly the same slots day to day</li></ul><h2><strong>Quality standards</strong></h2><table><thead><tr><th><p><strong>Do</strong></p></th><th><p><strong>Don't</strong></p></th></tr><tr><th><ul><li>Text placed tidily and fully inside the frame</li><li>Text large enough to read on a phone, but not overwhelming the image</li><li>Images in the intended order</li><li>The sound provided on the system</li><li>Correct format and aspect ratio</li><li>Captions exactly as provided</li><li>Publishing only in your own language</li><li>The post link pasted back on the platform</li></ul></th><th><ul><li>Text so large it covers the image</li><li>Text cut off at the edges or hidden behind the TikTok UI</li><li>A sound you picked yourself</li><li>Images out of order or missing</li><li>Low-quality, stretched or squashed images</li><li>Publishing in a language that isn't yours</li><li>Leaving comments unanswered</li><li>Forgetting to paste the link</li></ul></th></tr></thead></table><h2><strong>Comments</strong></h2><p>Check the comments on your posts. Reply where it makes sense, and don't leave questions hanging — engagement helps the post, and an abandoned comment section looks like an abandoned account.</p><h1><strong>5. Reviews &amp; feedback</strong></h1><p>Your manager checks your posts regularly and can send you feedback directly through the platform as a pop-up review. This is normal and not a warning — it is how we keep quality consistent across every country.</p><p>Common feedback you might get:</p><ul><li>Text too large, or badly placed</li><li>Wrong sound, or no sound</li><li>Wrong format</li><li>Low image quality</li><li>Irregular posting times, or a missed post</li><li>Comments left unattended</li><li>Link not pasted on the platform</li></ul><table><thead><tr><th><p><strong>When you get a review, apply the correction on your next post — not eventually.</strong></p><p>The same feedback given three times becomes a problem for your contract. Fixed the first time, it is simply a note.</p></th></tr></thead></table><h2><strong>What your manager checks every day</strong></h2><table><thead><tr><th><p><strong>Did you post twice?</strong></p></th><th><p>2 posts per day, every day</p></th></tr><tr><th><p><strong>Are the links on the platform?</strong></p></th><th><p>One link pasted per published post</p></th></tr><tr><th><p><strong>Are you getting views?</strong></p></th><th><p>Zero views usually means the account wasn't warmed up properly</p></th></tr><tr><th><p><strong>Are the posts correct?</strong></p></th><th><p>Text placement, provided sound, format, image quality</p></th></tr><tr><th><p><strong>Are your times consistent?</strong></p></th><th><p>Peak hours, roughly the same slots each day</p></th></tr></thead></table><h1><strong>6. Getting paid</strong></h1><p>Everything runs through Upwork — your contract, your milestones, and your payments. There are no side payments, and you should never be asked for one.</p><table><thead><tr><th><p><strong>Trial week</strong></p></th><th><p>$15, released once the trial week is complete</p></th></tr><tr><th><p><strong>Monthly</strong></p></th><th><p>$60 per month, as a fixed-price milestone</p></th></tr><tr><th><p><strong>Requirement</strong></p></th><th><p>2 posts per day, 7 days a week</p></th></tr><tr><th><p><strong>Where</strong></p></th><th><p>Upwork only</p></th></tr><tr><th><p><strong>Questions</strong></p></th><th><p>Message your hiring manager on Upwork or Slack</p></th></tr></thead></table><h2><strong>Missed posts</strong></h2><p>Missing the odd post happens, and we handle it with a conversation rather than money. But posting is the job, so there is a clear rule when it becomes a pattern:</p><table><thead><tr><th><p><strong>Up to 5 missed posts in a month</strong></p></th><th><p>No deduction — your manager will talk to you about it</p></th></tr><tr><th><p><strong>More than 5 missed in a month</strong></p></th><th><p>$1 is deducted per missed post</p></th></tr><tr><th><p><strong>How it is applied</strong></p></th><th><p>Taken off that month's payment, or from the next month if that payment has already gone out</p></th></tr></thead></table><p>If something genuinely comes up — illness, an emergency — tell your manager straight away rather than going quiet. A message costs you nothing; silence is what ends contracts. If you are unresponsive for 4 days, the contract is ended and we request a refund.</p><h1><strong>7. Slack &amp; questions</strong></h1><p>We have a Slack workspace for the whole programme. Join it as soon as you are hired — it is where you ask questions and follow updates.</p><p><a href="https://join.slack.com/t/sophia-system/shared_invite/zt-44pqj3z39-X4KkPQI6cwOwWE2LNaLbig">Join the Sophia Slack</a></p><table><thead><tr><th><p><strong>#welcome</strong></p></th><th><p>Start here — pinned onboarding information</p></th></tr><tr><th><p><strong>#questions</strong></p></th><th><p>Ask anything — your manager or another manager will answer</p></th></tr><tr><th><p><strong>#technical-issues</strong></p></th><th><p>Platform bugs, login problems, TikTok account problems</p></th></tr></thead></table><p><strong>Remember: your daily post links do not go in Slack. They go on the platform.</strong></p><p><em>Please ask in the channels rather than by direct message. Your question has probably been asked before, and the answer helps everyone else too.</em></p><h2><strong>Quick answers</strong></h2><h3><strong>I created my TikTok account but my manager can't find it.</strong></h3><p>Send them the direct link to your profile. If you didn't use exactly the handle shown in your Sophia space, either correct it or ask your manager to update it in the system.</p><h3><strong>Which email should I use for the TikTok account?</strong></h3><p>Your own — an existing address, or a new one you create for this. It is your account.</p><h3><strong>Can I use a different sound if I think it fits better?</strong></h3><p>No. Use the sound provided with the slideshow on the system.</p><h3><strong>I posted in the wrong language by mistake.</strong></h3><p>If it's getting good views, leave it. From then on, publish only in your own language.</p><h3><strong>My posts are getting no views at all.</strong></h3><p>Almost always an account that wasn't warmed up for a full 24 hours, or that started posting too early. Tell your manager — don't just keep posting into the void.</p><h3><strong>No slideshows have appeared in my calendar.</strong></h3><p>Check that your 24-hour warm-up has finished. If it has and there is still nothing, message your manager or post in #technical-issues. Don't invent your own content.</p><h3><strong>I can't post today.</strong></h3><p>Tell your manager before the deadline, not after. Planned absences are manageable; unexplained silence isn't.</p><h2><strong>The rules, short version</strong></h2><ul><li>Press “Start warm-up” and wait a full 24 hours before your first post.</li><li>2 posts per day, 7 days a week — including your trial week.</li><li>Use the sound provided on the system.</li><li>Paste every post link back on the platform.</li><li>Use exactly the TikTok identity assigned to you, with your own email address.</li><li>Only publish in your own language.</li><li>Apply feedback on your next post.</li><li>Everything goes through Upwork.</li><li>If something goes wrong, message your manager the same day.</li></ul></div>$guide_zone_a$ as html
)
insert into public.documents (cle, titre, titre_en, audience, ordre, contenu, contenu_en)
select 'guide_poster_zone_a', 'Creator Guide — Zone A (standard rate)', 'Creator Guide — Zone A (standard rate)', 'poster', 3, html, html
from src
on conflict (cle) do update set
  titre = excluded.titre,
  titre_en = excluded.titre_en,
  audience = excluded.audience,
  ordre = excluded.ordre,
  contenu = excluded.contenu,
  contenu_en = excluded.contenu_en,
  updated_at = now();

